package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface SettingLogRepository extends JpaRepository<SettingLog, Long> {

    /** The sheet's settings set, in the order set. */
    List<SettingLog> findBySheetIdOrderByIdAsc(String sheetId);

    /** The sheet as it stood at the end of a date, that date standing in for its today: every setting set while
     *  its today was on or before it. Only worked out, never saved. */
    default Sheet sheetAsOf(Sheet sheet, LocalDate date) {
        Sheet then = new Sheet(sheet.getId());
        then.setToday(date);
        then.setArchived(sheet.isArchived());
        for (SettingLog set : findBySheetIdOrderByIdAsc(sheet.getId())) {
            if (set.getMadeOn().isAfter(date)) {
                continue;
            }
            if (Sheet.POLICY_DATE.equals(set.getKey())) {
                then.setPolicyDate(set.getValue() == null ? null : LocalDate.parse(set.getValue()));
            } else if (Sheet.PERIOD_NUMBERING_FROM.equals(set.getKey())) {
                then.setPeriodNumberingFrom(set.getValue() == null ? null : LocalDate.parse(set.getValue()));
            } else {
                then.record(set.getKey(), set.getFromDate(), set.getValue());
            }
        }
        return then;
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import org.springframework.data.jpa.repository.JpaRepository;

public interface RateLogRepository extends JpaRepository<RateLog, Long> {

    /** The sheet's rates set, in the order set. */
    List<RateLog> findBySheetIdOrderByIdAsc(String sheetId);

    /** The sheet's rates as they stood at the end of a date: every rate set while the sheet's today was on or before
     *  it, each replacing the one its grade had for its from-date, as setting it did. Only worked out, never saved. */
    default List<Rate> ratesAsOf(String sheetId, LocalDate date) {
        List<Rate> rates = new ArrayList<>();
        for (RateLog set : findBySheetIdOrderByIdAsc(sheetId)) {
            if (set.getMadeOn().isAfter(date)) {
                continue;
            }
            Rate rate = rates.stream().filter(r -> r.getGrade().equals(set.getGrade())
                    && Objects.equals(r.getFromDate(), set.getFromDate())).findFirst().orElse(null);
            if (rate == null) {
                rates.add(new Rate(sheetId, set.getGrade(), set.getPct(), set.getFromDate(), set.getToDate()));
            } else {
                rate.setPct(set.getPct());
                rate.setToDate(set.getToDate());
            }
        }
        return rates;
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the new today from the body; refuses anything that is not a calendar date. */
public class ValidateToday {

    public record TodayRequest(String today) {
    }

    public void validate(@RequestBody TodayRequest request, Out<LocalDate> today) throws InvalidTodayException {
        String raw = request == null || request.today() == null ? "" : request.today().trim();
        try {
            today.set(LocalDate.parse(raw));
        } catch (DateTimeParseException e) {
            throw new InvalidTodayException(raw);
        }
    }
}

