// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
// A non-2xx answer: its status tells a refusal (400) from a conflict with someone else's save (409).
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

// A change sends the signed-in name (`user`) as `X-User`, URI-encoded (a header is Latin-1 only),
// so the server records who made it.
const jsonHeaders = (user?: string): Record<string, string> =>
  user ? { 'Content-Type': 'application/json', 'X-User': encodeURIComponent(user) } : { 'Content-Type': 'application/json' };

export function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body?: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: jsonHeaders(user),
    body: body === undefined ? undefined : JSON.stringify(body),
  });
}
import { useRef } from 'react';
import type { UseMutationResult } from '@tanstack/react-query';

// Submits a mutation at most once at a time: a second submit (a double click) before the first has
// answered is dropped, so it stores one record, not two. `isPending` alone is not enough: it only
// disables the button once React has re-rendered, which a fast second click can beat.
export function useSubmitOnce<D, V, C>(mutation: UseMutationResult<D, Error, V, C>) {
  const busy = useRef(false);
  return (variables: V) => {
    if (busy.current) return;
    busy.current = true;
    mutation.reset();
    mutation.mutateAsync(variables).catch(() => undefined).finally(() => { busy.current = false; });
  };
}
import { useRef, useSyncExternalStore } from 'react';

// The last action taken on each row, by row key. A row's cells come from separate slots, each with its own
// mutation; an error belongs to the action that raised it, so it is shown only while that action is still the
// row's latest — taking the next action on the row, in any of its cells, removes an old error.
const latest = new Map<string, symbol>();
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => { listeners.delete(listener); };
}

export function useRowAction(row: string) {
  const mine = useRef(Symbol(row));
  const current = useSyncExternalStore(subscribe, () => latest.get(row));
  return {
    /** Marks this cell's action as the row's latest; call it as the action is taken. */
    take: () => {
      latest.set(row, mine.current);
      listeners.forEach((l) => l());
    },
    /** Whether this cell's action is the row's latest, so its error may show. */
    isLatest: current === mine.current,
  };
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';

// The signed-in name and the active sheet id live in the URL (search params `user` and `sheet`).
// Everything else in the app is kept per sheet: a feature reads the sheet id from here and keys
// its queries under ['sheet', sheetId, ...], so loading a sheet re-reads all of them.
export const useCurrentUser = () => useSearchParam('user', asString);
export const useCurrentSheet = () => useSearchParam('sheet', asString);

// The active sheet as the store holds it: its id, its today and whether it is archived (then every
// change on it is refused). Every date decision and default
// date in the app uses the sheet's today (useSheetToday), never the browser's clock.
export type SheetInfo = { id: string; today: string; archived: boolean };

export const sheetQueryKey = (sheetId: string) => ['sheet', sheetId, 'info'] as const;

export function useSheetInfo() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: sheetQueryKey(sheet ?? ''),
    queryFn: () => getJson<SheetInfo>(`/api/sheets/${encodeURIComponent(sheet ?? '')}`),
    enabled: !!sheet,
  });
}

/** The sheet's today (YYYY-MM-DD), or undefined until the sheet is loaded. */
export const useSheetToday = () => useSheetInfo().data?.today;
import { useCallback, useState, useSyncExternalStore } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { AppSession } from '../../slots/defs/appSession';
import { useCurrentSheet, useCurrentUser } from './session';

// Whether every query kept for the sheet has been read at least once since it was (re-)loaded — so the
// sheet's id shows only once the screen holds what the store holds for it, not the empty or old data
// before. A refetch that keeps the data it had (after a change) does not hide it.
function useSheetRead(sheet: string | undefined): boolean {
  const queryClient = useQueryClient();
  const cache = queryClient.getQueryCache();
  const subscribe = useCallback((onChange: () => void) => cache.subscribe(onChange), [cache]);
  return useSyncExternalStore(subscribe, () => {
    if (!sheet) return false;
    const queries = cache.findAll({ queryKey: ['sheet', sheet] });
    return queries.length > 0 && queries.every((q) => q.state.status !== 'pending' || q.isDisabled());
  });
}

// Choose a sheet by typing its id and loading it. Loading (again) re-reads everything kept for it.
function SheetPicker() {
  const [user] = useCurrentUser();
  const [sheet, setSheet] = useCurrentSheet();
  const [id, setId] = useState('');
  const queryClient = useQueryClient();
  const load = useMutation({
    mutationFn: (sheetId: string) => putJson<{ id: string }>(`/api/sheets/${encodeURIComponent(sheetId)}`),
    onSuccess: async (loaded) => {
      // Drop what was read for it before, so the screen shows the store's data, never an older copy.
      await queryClient.resetQueries({ queryKey: ['sheet', loaded.id] });
      setSheet(loaded.id);
    },
  });
  const submit = useSubmitOnce(load);
  const read = useSheetRead(sheet);

  if (!user) return null;
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (id.trim()) submit(id.trim());
      }}
    >
      <input data-testid="sheet-id-input" placeholder="Sheet id" value={id} onChange={(e) => { setId(e.target.value); load.reset(); }} />
      <button type="submit" data-testid="sheet-load" disabled={load.isPending}>
        Load sheet
      </button>
      {sheet && read && (
        <span>
          Sheet <strong data-testid="sheet-current-id">{sheet}</strong>
        </span>
      )}
      {load.isError && <span data-testid="sheet-load-error">Could not load the sheet.</span>}
    </form>
  );
}

export const contribution = AppSession.fill({ order: 10, Component: SheetPicker });
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { AppSession } from '../../slots/defs/appSession';
import { useCurrentSheet, useCurrentUser, useSheetInfo, sheetQueryKey, type SheetInfo } from './session';

// The sheet's today: shown and changeable here. Changing it re-reads the whole sheet, since every
// date decision in the app depends on it. The sheet is archived here too (a steward only); the two
// share the sheet's one error element, which either action clears.
function SheetToday() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const info = useSheetInfo();
  const [date, setDate] = useState('');
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: (today: string) =>
      putJson<SheetInfo>(`/api/sheets/${encodeURIComponent(sheet ?? '')}/today`, { today }, user),
    onSuccess: async (saved) => {
      queryClient.setQueryData(sheetQueryKey(saved.id), saved);
      await queryClient.invalidateQueries({ queryKey: ['sheet', saved.id] });
    },
  });
  const submit = useSubmitOnce(save);
  const archive = useMutation({
    mutationFn: () => putJson<SheetInfo>(`/api/sheets/${encodeURIComponent(sheet ?? '')}/archive`, undefined, user),
    onSuccess: (saved) => queryClient.setQueryData(sheetQueryKey(saved.id), saved),
  });
  const submitArchive = useSubmitOnce(archive);
  const shown = info.data?.id === sheet ? info.data : undefined;

  if (!user || !sheet) return null;
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        archive.reset();
        submit(date.trim());
      }}
    >
      <span>
        Today <strong data-testid="sheet-today">{shown ? shown.today : ''}</strong>
      </span>
      <input
        data-testid="sheet-today-input"
        placeholder="YYYY-MM-DD"
        value={date}
        onChange={(e) => { setDate(e.target.value); save.reset(); archive.reset(); }}
      />
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set today
      </button>
      <span>
        Archived <strong data-testid="sheet-archived">{shown ? (shown.archived ? 'yes' : 'no') : ''}</strong>
      </span>
      <button
        type="button"
        data-testid="sheet-archive"
        disabled={archive.isPending}
        onClick={() => { save.reset(); submitArchive(undefined); }}
      >
        Archive sheet
      </button>
      {save.isError && <span data-testid="sheet-error">Could not change the sheet's today.</span>}
      {archive.isError && <span data-testid="sheet-error">Could not archive the sheet.</span>}
    </form>
  );
}

export const contribution = AppSession.fill({ order: 20, Component: SheetToday });
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { createFileRoute } from '@tanstack/react-router';
